(
        '20940',
        'Issue on screening alerts',
        'Dears,    Kindly be informed that there aren’t any alerts for screening on the system from 22/12/2025 till now , please check     And for 21/12 there are 20963 items',
        'Dear @Oula Michel,    Based on our web session, please be informed that the issue related to the screening configuration, specifically the “watchlist upload flag “ wasn’t active. In addition, the query related to the “New Customer” screening should be based on “DATE_OPEN = TRUNC(SYSDATE) – 1 instead of DATE_OPEN = SYSDATE – 1” since SYSDATE includes the time component.    We have resolved these issues, which may have occurred by mistake, and refilled the missing screening alerts from “22-Dec-2025 until today”. Accordingly, the alerts for this period have now appeared in the system as expected, under day date = “20-Jan-2026” for both NEW and DELTA functions.      Kindly check the alerts and share your feedback.',
        '2026-01-19T00:00:00.000Z'::timestamptz,
        '2026-01-20T00:00:00.000Z'::timestamptz,
        '015a7170-65d3-490b-bd00-2c41faabf8f9'::uuid,
