(
        '20961',
        'ETL Failure',
        'Dear Team,    Need urgent assistance, ETL failed on both new and old systems',
        'Dear Mahin,    Based on our web session, kindly find below the status:      • Issue Reported by the customer: ETL Failure.    • Status: Solved.    • Problem description: The data extraction failed on both ETL servers due to the following:    1- New ETL server “Sybase IQ – Number of unique values exceeded for index BI_DWH.PIO_STOP_PAYMENTS.CUS_NUM_LF” This indicates that an IQ LF (Low Fast) index exists on the CUS_NUM column, and the number of distinct values exceeded the 10,000 limit, noting that Sybase IQ does not auto-expand LF indexes.    2- OLD ETL SERVER “Tried to insert a duplicate value into a unique index BI_DWH.PIO_CUSTOMER_CLASSIFICATION.ASIQ_IDX_1887_110_HG” This indicates that more than one row had the same values for the HG unique index columns.    • Action Taken – recommended solution: Based on our web session, kindly to be informed that the issue was resolved by:    1- New ETL server The problematic index BI_DWH.PIO_STOP_PAYMENTS.CUS_NUM_LF was dropped, and the expandable index BI_DWH.PIO_STOP_PAYMENTS.CUS_NUM_HG was retained.              2- OLD ETL SERVER The DF_CUST_CLASS ETL dataflow was enhanced to ensure that no duplicate records are inserted into the table BI_DWH.PIO_CUSTOMER_CLASSIFICATION.                 Considering that the ETL daily fill has been successfully completed on both servers.    Kindly check from your side and confirm to close this ticket.     Best Regards,',
        '2026-01-21T00:00:00.000Z'::timestamptz,
        '2026-01-21T00:00:00.000Z'::timestamptz,
