        'Create Document issue inside Arabic Folder named',
        'Dear support    could you check with us why we cannot upload documents inside the Arabic Folder Names in DMS system, pls let me know when you have time.',
        'Dear Sangar,  We would like to inform you that the issue related to creating files inside folders with Arabic names is a known limitation in the current DM version (16.1).  In DM version 16.1, Arabic (Unicode) characters are not fully supported in folder and file system paths. As a result, errors may occur when using Arabic folder names, while English folder names work as expected.',
