(
        '20919',
        'TDE encryption under SQL database server - Study',
        'Dears,    I trust this Ticket finds you well.    We have received reports of audit related to TDE encryption under SQL database servers. To address this note, we require clarification regarding the compatibility of Piotech product (ETL) with TDE encryption under SQL database servers.    Your prompt advice on this matter would be greatly appreciated.    For more details, please review below document link.     link: https://learn.microsoft.com/en-us/sql/relational-databases/security/encryption/transparent-data-encryption?view=sql-server-ver17',
        'Dear Laith,    Regarding your query, applying Transparent Data Encryption (TDE) on SQL Server will not have a functional impact on the SAP Data Services (DS) or SAP Information Platform Services (IPS) repositories.    From an application perspective:  • SAP DS and SAP IPS interact with the database at the SQL layer and are transparent to TDE.  • No configuration changes are required on the SAP DS or SAP IPS side when TDE is enabled.  • Encryption and decryption are handled entirely by SQL Server.    However, from a technical and performance perspective, the following considerations apply:  • Enabling TDE may introduce additional CPU overhead due to encryption/decryption processes.  • There may be I/O performance impact, particularly during high-volume read/write operations such as:  o SAP DS batch jobs  o Metadata updates  o Repository-intensive operations  • Initial TDE enablement will trigger a full database encryption scan, which may temporarily increase resource utilization.    Based on the above, while TDE is supported and should not affect functionality, we strongly recommend:  • Enabling TDE initially on a test environment  • Executing a full SAP DS and SAP IPS workload test cycle  • Monitoring CPU, I/O, and job execution performance before enabling TDE on the production environment    Please let us know if you need any additional technical details or support.',
        '2026-01-20T00:00:00.000Z'::timestamptz,
        '2026-01-26T00:00:00.000Z'::timestamptz,
        '015a7170-65d3-490b-bd00-2c41faabf8f9'::uuid,
