(
        '21022',
        'Time deposits issue',
        'Dear Support Team,    Please be informed that we are observing an issue on production that Maturity Date and DEPOSITS_EXIPRY_DATE is no longer uploaded into the DWH since 25-01-2026, please your immediate action is required.',
        'Dears @Mohammad.Romana@tnb.ps, @Ghassan Siyam,    Please be informed that the reported issue is related to 26 January, and the time deposit source on your core system is not historical. Accordingly, it is necessary to retrieve backup for this date in order for us to provide an accurate and definitive response to the issue.    Noting that we have reviewed the ETL process and the table used to populate the DWH. This table is joined with the account and branch tables, and a condition is applied when reading time deposit data whereby the value date must be less than or equal to the data date. It is highly likely that the issue is related to this condition.  During our review, we observed that for 27 January, the value date was 27 January 2026, whereas for 25 January 2026, the value date was recorded as 2025.    Kindly review this from your side and advise if you require any additional support or information from us.',
        '2026-01-29T00:00:00.000Z'::timestamptz,
        '2026-01-28T00:00:00.000Z'::timestamptz,
