        'Dear All,    These transfers were not appeared in PioTech alerts, although the beneficiary name mentioned in manual and sanctions lists.',
        'Dear @Shaza,    Based on our web session, kindly find below the status:     • Issue Reported by the customer: Missing Transfer Screening Alerts Despite Matching Beneficiary Names .      • Status: Solved.     • Problem description: The two alerts did not appear initially because one of them was generated on a different date, while the other alert was not reflected correctly in our tables.    • Action Taken – recommended solution: Based on our web session, please note that the alert with customer number ‘OUT-6511126000001’ already existed on ‘21-Jan-2026’. After modifying the related matter, the alert is now appearing correctly on ‘05-Jan-2026’. Regarding the other alert with customer number ‘OUT-6511126000074’, the customer name was not correctly retrieved on our tables ,After resolving this issue the alert now appearing on ’19-jan-2026’.              Please note that while we were working the screening alerts for today temporarily disappeared. However, they have now reappeared, and everything is functioning normally.      ? Kindly check and confirm so we may proceed with closing the ticket.  Dear @Shaza,  Based on our web session, please note that the customer number ‘OUT-6511126000001’ is the same one mentioned in your previous email. There was an issue related to trimming the customer name from our tables. After resolving this issue, the customer is now reflected correctly, as shown in the picture below.',
