        '21073',
        'Report closed alert',
        'Dears,  we need clarification about closed alert report as if the user level 1 the report doesn''t appear all closed alerts for this user,',
        'Dears,    Based on our web session, kindly find below the status:     • Issue Reported by the customer: Report closed alert.     • Status: Done.     • Problem description:. Report closed alert    • Action Taken – recommended solution: Based on our web session, kindly be informed that there is no issue with the reports.  However, regarding the alerts, the SEND_BY field is updated based on the user code of the last user who worked on the alert.  In cases where an officer works on multiple alerts and a senior officer later reviews or updates them, the SEND_BY value is automatically updated to the senior officer’s user code.  Accordingly, the alerts cannot appear under a single user, as the SEND_BY field keeps changing with each update.    Kindly check from your side and confirm so we can proceed with closing this ticket.',
