        'Create Cliq + scenarios',
        'Create Cliq + scenarios',
        'Dear @Mohammed,  Please be informed that all Qliq+ scenarios have been successfully implemented in the test environment. We kindly request the following from your side in order to proceed with AML filling data.  1. The source for the customer risk level and the transaction sender code  2. Confirmation that Qliq+ transactions are available in the test environment  3. The dates of the new transactions so we can update our records accordingly   We are awaiting your update to proceed with returning the results to the AML system, so the Compliance team can begin their testing.  Kindly find the below scenario names and codes for the created scenarios:  666666667 Any customer receives 5000 JOD via Cliq + and then performs debit transactions on the same day  666666668 Any customer receives cumulative incoming remittances equal or grater than 10,000 JOD via CliQ within one month  666666669 Any customer receives incoming CliQ Plus transactions originating from high-risk countries  666666670 Any customer receives more than 5 incoming CliQ Plus transactions from the same sender within the same day.',
