        '21117',
        'Review of Scenario Issues',
        'Dear Team  I hope this email finds you well.  Please note that following our recent review, we identified the below issues that require further discussion:  •2000037 scenario: False positive alerts are still being generated despite the latest amendments.  •KYC scenario: No alerts have been generated since 1 December, which indicates a potential issue with scenario functionality.  We would like to schedule a meeting to review these points and confirm the correct implementation and behavior of both scenarios.  Kindly share your availability for a suitable time.  Best,',
        'Dears,    Based on our web session, please find below the PIO-TECH response for each point:    • 2000037 scenario: False positive alerts are still being generated despite the latest amendments.    ? PIO-TECH Response: After our investigation, we confirmed that the alerts appearing in the system are correct and there is no issue. It seems that a modification was applied after “20-Nov-2025” at the database level after reviewing the relevant tables that store the scenario rules. Therefore, any alerts generated before this date or not aligned with the updated parameter (number of transactions = 10) are expected, as they were generated based on the previous value (number of transactions = 5), as shown in the picture below.                • KYC scenario: No alerts have been generated since 1 December, which indicates a potential issue with scenario functionality    ? PIO-TECH Response: We have traced the AML engine responsible for generating alerts on “01-Feb-2026” as a sample date. Alerts are now appearing for this scenario on the mentioned date as expected. Kindly check the results for this month and share your feedback.',
