(
        '21141',
        'Check query',
        'Dears,    I want to check this query correct for Last system login for each user + users who have never logged in  SELECT *  FROM (   SELECT   u.FIRSTNAME,   u.LASTNAME,   u.EMAILADDRESS,   u.USERNAME,   -- NVL(MAX(TO_DATE(t.LOGIN_DATE, ''DD/MM/YYYY'')), NULL) AS LAST_LOGIN_DATE,   -- MAX(at.LOG_DATE) AS LAST_LOG_DATE,   CASE   WHEN GREATEST(   NVL(MAX(TO_DATE(t.LOGIN_DATE, ''DD/MM/YYYY'')), DATE ''1900-01-01''),   NVL(MAX(at.LOG_DATE), DATE ''1900-01-01'')   ) = DATE ''1900-01-01''   THEN NULL   ELSE GREATEST(   NVL(MAX(TO_DATE(t.LOGIN_DATE, ''DD/MM/YYYY'')), DATE ''1900-01-01''),   NVL(MAX(at.LOG_DATE), DATE ''1900-01-01'')   )   END AS LAST_ACTIVITY_DATE   FROM uni_repos.pio_users u   LEFT JOIN uni_repos.PIO_USERS_LOGIN_TRAIL t   ON t.USER_NAME = u.USERNAME   LEFT JOIN uni_repos.PIO_LOGS_AUDITTRAIL at   ON at.USERNAME = u.USERNAME   GROUP BY   u.FIRSTNAME,   u.LASTNAME,   u.EMAILADDRESS,   u.USERNAME  ) sub  --WHERE LAST_ACTIVITY_DATE IS NOT NULL  ORDER BY LAST_ACTIVITY_DATE ASC NULLS FIRST;',
