(
        '21169',
        'Requires Manual URL Addition in Microsoft Edge',
        'We are currently experiencing an issue with the Archiving System. The system does not open or function properly unless the specific system URL is manually added to the trusted or allowed sites in Microsoft Edge.  This behavior is affecting multiple users and is causing operational delays, as the system should normally open without requiring manual browser configuration.  Kindly investigate the issue and advise on the root cause. We would appreciate a permanent solution that ensures the system works properly without the need to manually adjust browser settings on each device.',
        'Dear Sara,  Below are the complete steps to configure Microsoft Edge IE Mode for OpenText eDOCS DM 16, starting from creating the folder until full functionality (including folder retrieval) is working.  STEP 1 – Create IE Mode Folder  1. Open File Explorer.  2. Go to Local Disk (C:).  3. Create a new folder named:  IE_Mode  Final path:  C:\IE_Mode  STEP 2 – Create Enterprise Mode XML File  1. Inside C:\IE_Mode, create a new text file.  2. Rename it to:  sites.xml  Make sure file extensions are visible and it is not named sites.xml.txt.  3. Open sites.xml in Notepad.  4. Paste the following content:  5. Save and close the file.    STEP 3 – Install Microsoft Edge Administrative Templates (ADMX)  1. Download Microsoft Edge Policy Templates from Microsoft.  2. Extract the ZIP file.  3. Go to:  windows ? admx  4. Copy:  o msedge.admx  o msedgeupdate.admx  o msedgewebview2.admx  To:  C:\Windows\PolicyDefinitions  5. Copy the language folder (for example en-US) from admx into:  C:\Windows\PolicyDefinitions\en-US  STEP 4 – Configure IE Mode via Group Policy  1. Press Windows + R.  2. Type:  gpedit.msc  3. Navigate to:  Computer Configuration  ? Administrative Templates  ? Microsoft Edge  4. Configure the following policies:  A. Configure Internet Explorer integration  Set to: Enabled  Option: Internet Explorer mode  B. Configure the Enterprise Mode Site List  Set to: Enabled  Value:  file:///C:/IE_Mode/sites.xml  5. Click Apply ? OK.    STEP 5 – Verify Registry (Optional Check)  Open Registry Editor:  Windows + R ? regedit  Go to:  HKEY_LOCAL_MACHINE\SOFTWARE\Policies\Microsoft\Edge  Confirm these entries exist:  InternetExplorerIntegrationLevel = 1  InternetExplorerIntegrationSiteList = C:\IE_Mode\sites.xml    STEP 6 – Add Site to Trusted Sites  1. Press Windows + R.  2. Type:  inetcpl.cpl  3. Go to Security tab.  4. Select Trusted Sites ? Click Sites.  5. Add:  http://172.30.21.1  6. Uncheck “Require server verification (https:)”.  7. Click Add ? Close.    STEP 7 – Configure ActiveX Settings  In Internet Properties:  Security ? Trusted Sites ? Custom Level  Enable the following:  • Download signed ActiveX controls  • Run ActiveX controls and plug-ins  • Script ActiveX controls marked safe  • Active scripting  Set “Initialize and script ActiveX not marked safe” to Prompt (or Enable if required).  Click OK.    STEP 8 – Disable 64-bit IE Protected Mode (CRITICAL FOR DM 16)  1. Open:  inetcpl.cpl  2. Go to Advanced tab.  3. Uncheck:  o Enable Enhanced Protected Mode  o Enable 64-bit processes for Enhanced Protected Mode  4. Click Apply ? OK.  5. Restart the computer.    STEP 9 – Verify IE Mode is Working  1. Open Microsoft Edge.  2. Browse to:  http://172.30.21.1/cyberdocs  3. Confirm:  o Page opens in Internet Explorer mode.  o IE icon appears in address bar.  o Zone = Trusted.  o Protected Mode = Off.  4. Log in to eDOCS DM 16.  5. Confirm folders load correctly.    FINAL RESULT  After completing the above steps:  • IE Mode will not expire.  • eDOCS DM 16 loads correctly.  • Folder retrieval works.  • No HTTPS conversion required.    Please keep these settings unchanged to maintain stability.',
        '2026-02-25T00:00:00.000Z'::timestamptz,
