        '21232',
        'Screening delta issue',
        'Dear team     We are writing to bring to your attention a matter of significant concern that requires urgent review.  This matter constitutes a formal escalation regarding a critical compliance failure that demands your immediate intervention.    On 24 February 2026, (4) new names were officially added to the United Nations (UN) sanctions list. However, after conducting a verification through the AML Watchlist Checker on Piotech, these names do not appear in your system.    This is an extremely serious compliance gap. The UN sanctions list is a primary and globally binding source for sanctions screening, and any failure to reflect updates exposes the organization to significant regulatory, legal, and reputational risks.    We require an immediate explanation as to:  1.Why these names have not been updated in your system.  2.What controls are in place to ensure real-time or timely synchronization with UN sanctions updates.  3.What corrective actions will be taken to resolve this issue without delay.    Given the gravity of this matter, we expect a prompt response and confirmation of corrective action as soon as possible. This issue must not be treated as an ordinary or minor matter; UN sanctions compliance is non-negotiable.    Please treat this matter with the highest level of urgency.',
