(
        '21290',
        'Screening session',
        'Screening session',
        'Dear @Hla Ahmad - E-Services & CBS Services Officer,    Thank you for taking the time to attend today’s meeting. Below is a summary of the main topics we discussed regarding the screening process and watchlist monitoring:    Screening Overview  Explained the concept of screening and its role in ensuring compliance with AML and sanctions regulations.  Screening is used to check customer data against global sanctions and risk lists to ensure that the organization does not conduct business with sanctioned or high-risk individuals or entities.  Sanctions and Watchlists  Reviewed the main sanctions lists used in the screening process, including those issued by the United Nations, European Union, and the Office of Foreign Assets Control.  Clarified the difference between OFAC lists and non-OFAC lists, as well as the purpose of monitoring multiple international watchlists.  Watchlist Checker  Discussed how the Watchlist Checker functions as the engine responsible for comparing customer data against sanctions and watchlists.  Explained that the system analyzes names, aliases, and other available identifiers to identify potential matches.  Filtered method preferred to use as Fuzzy.  Matching Logic and Minimum Score  Explained the concept of matching scores used by the system to measure similarity between customer data and entries in watchlists.  Discussed the role of the Minimum Score, which defines the minimum similarity percentage required for the system to generate an alert.  Note: The minimum score is now able to be changed in the interface.  Alert Generation  Clarified how alerts are created when a match score exceeds the defined minimum threshold.  Explained that these alerts are then reviewed by the compliance team to determine whether they represent a true match or a false positive.  Delta New Customers Watchlists  Introduced the concept of Delta Screening, where the system checks newly added watchlist entries against existing customers or newly onboarded customers.  This process ensures that updates in sanctions lists are continuously monitored without re-screening the entire customer base.  Additionally, we would like to emphasize the importance of maintaining both the correct order and accuracy of the information provided in the template attached to upload a Manual list. Kindly ensure that the following fields are completed correctly and in the specified sequence. Please also note that the names listed below must be filled in accordingly, as the scanning priority will follow the order provided. Ensure that no placeholders such as “NUL”, “NA”, or similar values are entered in empty name fields. If a name is not available, the corresponding cell should be left blank.      The required fields are:      AKA First Name  AKA Last Name  First Name  Last Name  Full Name (Native)  SDN Type (Capital Letters)    Please let me know if you have any further questions or if additional clarification is needed on any of the points discussed.',
        '2026-03-08T00:00:00.000Z'::timestamptz,
        '2026-03-10T00:00:00.000Z'::timestamptz,
