        'Dear Abraham,    Based on our web session, kindly find below the status:      • Issue Reported by the customer: Data extraction failed.    • Status: Solved.    • Problem description: The ETL data extraction failed on March 17, 2026, due to the following reasons:     1- The ETL process failed at the ODS level due to a data size mismatch, where the data retrieved from the core database table exceeded the defined length/datatype of column (CUR_PRI) in table (BI_ODS.TELL_ACT).         2- The ETL process failed at the DWH level due to insufficient memory allocation within the SSIS runtime environment. Specifically, the ETL data flow (DF_PIO_RISK_PORTFOLIO_CDC) was unable to allocate the required buffer memory during execution, which caused the ETL package to terminate.         • Action Taken – recommended solution: Based on our web session, the issue has been successfully resolved after implementing several enhancements to both ETL data flows (DF_TELL_ACT) and (DF_PIO_RISK_PORTFOLIO_CDC). The ETL job was re-executed for March 17 and 18, 2026, and completed successfully.    Kindly check from your side and confirm to close this ticket.     Best Regards,',
