(
        '21382',
        'ETL batch issue',
        'Dear Mohammad,    As discussed over the phone, kindly manage to connect and check our ETL as we had faced a strange behavior today as shown below, the Jcb_load_plan took more than usual and stopped at Mar 18, 2026 5:38:10 AM, another job had started at Mar 18, 2026 5:06:39 AM automatically and took its usual time and the inh_2 has started at Mar 18, 2026 9:16:54 AM after it scheduled time and give wrong timing for start time and end time.',
        'Dear Mohammad,    Based on our Teams session, kindly note that there is no issue with the real-time ETL job schedule. The job is running as expected at its scheduled time (1:30 AM).    As discussed during the session, this is a known issue similar to what we encountered on the old ETL server, where the ODI Load Plan execution log displays an incorrect timestamp. A workaround has been implemented and tested successfully, and the issue is now resolved.    Regarding the unusual ETL behavior observed on March 18, 2026, analysis indicates that the (JCB_LOAD_PLAN) ETL job might mistakenly triggered twice. One of the executions failed because the ETL process attempted to access or modify (Insert/Update) tables (BI_ODS.LOAN_TAB or BI_ODS.LOAN_INS) that were locked by another active session. Since the process did not wait for the lock to be released, it failed immediately. The other execution completed successfully.    Based on the above, we consider this case closed.    Best Regards,',
        '2026-03-18T00:00:00.000Z'::timestamptz,
        '2026-03-19T00:00:00.000Z'::timestamptz,
