(
        '21403',
        'Schedule emails',
        'Dears,    Kindly note that a lot of schedule email return error as below shown, the error description is   server error. [SSL negotiation has failed during setup of the SMTP server connection, please ensure your SSL configuration is correct on both the client and the server. We need to connect with us to check issue reason.    Note: some emails delivered successfully without issues.',
        'Dear @Samer Huwwari,     The issue has been resolved following the identification of the root cause, which was an unannounced certificate update on the Microsoft 365 platform.     Technical Root Cause     The connection failure was caused by a rotation of the Microsoft 365 root certificate.  Validation using OpenSSL confirmed that the application server could no longer establish a trusted SSL handshake due to reliance on an outdated certificate store.  This change was introduced externally without prior notification from Microsoft or SAP.     Resolution And Action Taken      . Certificate Migration: Converted the new DigiCert Global Root G2 certificate into the required .PSE (Personal Security Environment) format.   . Configuration Update: Manually defined the explicit certificate paths within the SAP BI configuration to bypass resolution errors with default parameters.   . Service Optimization: Performed a full restart of the SAP BI Adaptive Job Servers, cleared orphan background processes (java.exe), and purged stale cache files to ensure the system initialized using the new security chain.     Current Status     The SAP BI services have successfully rebuilt the required security caches and are now communicating with the Microsoft 365 SMTP gateway using the updated certificate. All email schedules are back to a "Success" state.     Recommended Suggestions to be considered in the future     To avoid such cases in the future, it is highly recommended to minimize the number of schedule reports by review them, and makes sure only to keep what is used, and remove all unnecessary schedule reports from the daily schedule. Also, it is extremely important to allow the business users to have a certain access on their reports in case any interruption is done on the mailing system, since this is a possible and may happen in the future.',
        '2026-03-25T00:00:00.000Z'::timestamptz,
        '2026-03-29T00:00:00.000Z'::timestamptz,
