(
        '21443',
        'Fill issue',
        'Dear All,    The data not loaded for 29-03.',
        'Dear Mohammad,    Based on our web session, kindly be informed that the ETL daily job for the date March 29, 2026 was completed successfully.  As per the trace performed, it seems that the issue is caused by a Daylight Saving Time (DST) / time-zone shift on the server, which changed the system time offset, This time-zone change occurred after 1:00 AM and shifted the system time by +1 hour.    As a result:  • The Oracle system time shifted by +1 hour.  • ODI captured that shifted time in the global variable.  • Since the ODI global variable is based on the maximum pre_bank_date from the core banks process table, it captured 01:00:00 instead of midnight.  • The variable was inserted into a DATE column without truncation.    It is important to note that a DATE column in Oracle is not “date only”; it stores:  (year, month, day, hour, minute, and second).    Therefore, if the ETL variable value became 03/29/2026 01:00:00 AM, Oracle inserted exactly that value into the target DATE column, resulting in storing both date and time in the column.  In summary, the ETL stored date and time values because the DST/time-zone change affected the system time, which was captured by ODI and inserted into Oracle without truncation.    As agreed during our phone discussion, we will monitor tonight’s ETL daily fill to confirm that the issue does not recur and that the data are filled correctly without any issues.    Best Regards,',
        '2026-03-30T00:00:00.000Z'::timestamptz,
        '2026-03-30T00:00:00.000Z'::timestamptz,
        '015a7170-65d3-490b-bd00-2c41faabf8f9'::uuid,
